OLD_PLACEHOLDERS = ['Дәмді Market', 'Ақмешіт супермаркет', 'Сырдария дүкені', 'Береке', 'Үй жанындағы дүкен', 'Торговая точка из 2ГИС', 'Торговая точка из ссылки 2GIS']

class Command(BaseCommand):
    help = 'Загружает каталог СЗПТ и подтверждённые карточками 2GIS социальные магазины без цен.'
    def handle(self, *args, **options):
        for name, unit, category in PRODUCTS:
            Product.objects.update_or_create(name=name, defaults={'unit': unit, 'category': category, 'is_active': True})
        Store.objects.filter(name__in=OLD_PLACEHOLDERS).update(is_active=False)
        for name, address, district, latitude, longitude, source_url in STORES:
            Store.objects.update_or_create(name=name, defaults={'address': address, 'district': district, 'latitude': latitude, 'longitude': longitude, 'source_url': source_url, 'is_active': True})
        self.stdout.write(self.style.SUCCESS(f'Загружено {len(PRODUCTS)} товаров и {len(STORES)} магазинов. Цены не заданы.'))
